fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition: start + sub.len() <= main.len()
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    let main_len = main.len();
    let sub_len = sub.len();

    // Empty sub always qualifies
    if sub_len == 0 {
        return true;
    }

    // If sub longer than main, can't be a subarray
    if sub_len > main_len {
        return false;
    }

    // Iterate over all valid start indices
    for start in 0..=(main_len - sub_len) {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}